// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Bound seed to something reasonable
        uint256 value = bound(seed, 1, 100);

        // Make a call that passes require(msg.value == 10 ether) and require(block.timestamp > pastBlockTime)
        // We need to manipulate block.timestamp and block.number to avoid triggering the if branch
        vm.warp(block.timestamp + 1000); // ensure timestamp > pastBlockTime

        // Ensure block.number % 15 != 0 so the transfer does not happen
        uint256 blockNum = block.number;
        if (blockNum % 15 == 0) {
            // If it is exactly divisible, we cannot avoid the transfer, but we can test a different case
            // Since we cannot change block.number directly, we skip this case and assume it's not divisible
            vm.assume(block.number % 15 != 0);
        }

        // Now call fallback with 10 ether
        (bool success,) = address(c).call{value: 10 ether}("");
        if (success) {
            // The call succeeded, so pastBlockTime was updated
            // According to reference, pastBlockTime should be block.timestamp + 1
            // According to bug, pastBlockTime should be block.timestamp
            // So we check: pastBlockTime is strictly greater than block.timestamp when the call was made
            // But we cannot know the exact block.timestamp inside the call, we only know it's after warp
            // So we use a different assertion: pastBlockTime should be > block.timestamp (from before call)
            // Actually, since we warped to a future time, block.timestamp inside fallback is block.timestamp at call time
            // So we can check: c.pastBlockTime() > block.timestamp (the current one after call)
            // Bug: pastBlockTime = block.timestamp (equal to call time) so <= current
            assertTrue(c.pastBlockTime() > block.timestamp, "pastBlockTime should be > current timestamp");
        }
    }
}

